//go:build acceptance

// Package acctest provides helpers for running acceptance tests with VCR
// (cassette recording and replay) support against the F5XC Terraform provider.
//
// # VCR Modes
//
// Tests are controlled by the VCR_MODE environment variable:
//
//   - (unset / LIVE): direct live API calls, no cassettes involved.
//   - RECORDING: live API calls + write cassette files to disk.
//   - REPLAYING: replay from previously recorded cassettes, no live calls.
//
// # Usage
//
// Wrap every acceptance test case with [VcrTest] instead of calling
// resource.Test directly:
//
//	func TestAccResourceAutoF5XCFoo_basic(t *testing.T) {
//	    t.Parallel()
//	    acctest.VcrTest(t, resource.TestCase{
//	        PreCheck:                 func() { acctest.AccTestPreCheck(t) },
//	        ProtoV6ProviderFactories: acctest.ProtoV6ProviderFactories(t),
//	        Steps: []resource.TestStep{ ... },
//	    })
//	}
//
// # Cassette Layout
//
// Cassette files are stored alongside the test files that create them:
//
//	test/acctest/resource/cassettes/<TestName>.yaml   – resource tests
//	test/acctest/data/cassettes/<TestName>.yaml       – data source tests
