// VCR mode constants matching the VCR_MODE environment variable values.
const (
	vcrModeLive      = ""
	vcrModeRecording = "RECORDING"
	vcrModeReplaying = "REPLAYING"
)

const (
	docExampleCategoryResources   = "resources"
	docExampleCategoryDataSources = "data-sources"
)

// VcrTestOptions defines optional behaviors for acceptance test execution.
//
// Why: Acceptance runs are the source of truth for realistic examples, but we
// must keep export behavior explicitly opt-in and deterministic per test.
//
// How: The wrapper reads these options after the test run completes. When
// DocExampleCapture is enabled and the test passed, it extracts the first
// create-step config and writes it under the examples tree.
//
// Parameters:
//   - DocExampleCapture: enables pass-gated example export for the current test.
//   - DocExampleOutputRoot: optional override for examples root path. When empty,
//     defaults to f5xc/terraform/tpf/examples relative to this helper package.
//   - DocExampleConfig: optional explicit Terraform config text used for export.
//     When empty, exporter falls back to the first create-step config from tc.
//
// Returns:
//   - VcrTestWithOptions applies the options and performs side effects only
//     after a successful test run.
//
// Example:
//
//	acctest.VcrTestWithOptions(t, tc, acctest.VcrTestOptions{
//		DocExampleCapture: true,
//	})
type VcrTestOptions struct {
	DocExampleCapture    bool
	DocExampleOutputRoot string
	DocExampleConfig     string
}

// docExampleTarget describes where a captured example should be written.
type docExampleTarget struct {
	category   string
	folderName string
}

// vcrMode returns the current VCR mode from the VCR_MODE environment variable,
// normalised to upper-case.
func vcrMode() string {
	return strings.ToUpper(strings.TrimSpace(os.Getenv("VCR_MODE")))
}

// IsVCRReplaying reports whether the test process is running in replay mode.
// Destroy-check helpers use this to skip live API polling.
func IsVCRReplaying() bool {
	return vcrMode() == vcrModeReplaying
}

// VcrTest is the primary entry-point for acceptance tests.  It wraps
// [resource.Test] with VCR recording / replay logic driven by VCR_MODE:
//
//   - LIVE (default): calls resource.Test directly against a live API.
//   - RECORDING:      records all HTTP interactions to a cassette file.
//   - REPLAYING:      serves responses from a previously recorded cassette.
//
// Cassette files are placed in a "cassettes/" sub-directory relative to the
// source file of the calling test, so resource and data-source cassettes are
// kept separate automatically.
func VcrTest(t *testing.T, tc resource.TestCase) {
	VcrTestWithOptions(t, tc, VcrTestOptions{})
}

// VcrTestWithOptions runs a test case with VCR behavior and optional
// post-success doc-example capture.
func VcrTestWithOptions(t *testing.T, tc resource.TestCase, opts VcrTestOptions) {
	t.Helper()

	// Resolve the cassette file path from the calling test's source location.
	cassetteName, err := cassettePath(t)
	if err != nil {
		t.Fatalf("[VCR] cannot determine cassette path: %v", err)
	}

	switch vcrMode() {
	case vcrModeRecording:
		vcrRecord(t, tc, cassetteName)
	case vcrModeReplaying:
		vcrReplay(t, tc, cassetteName)
	default:
		// LIVE – no cassette involvement
		resource.Test(t, tc)
	}

	if opts.DocExampleCapture {
		captureErr := captureDocExampleFromTestCase(t, tc, opts)
		if captureErr != nil {
			t.Logf("[DOC-EXAMPLE] skipped capture: %v", captureErr)
		}
	}
}

// captureDocExampleFromTestCase exports the first create-step config as an
// example file only when the test has passed.
func captureDocExampleFromTestCase(t *testing.T, tc resource.TestCase, opts VcrTestOptions) error {
	t.Helper()

	if t.Failed() {
		return fmt.Errorf("test failed; export is pass-gated")
	}

	config := strings.TrimSpace(opts.DocExampleConfig)
	if config == "" {
		var ok bool
		config, ok = firstCreateStepConfig(tc)
		if !ok {
			return fmt.Errorf("no suitable create step config found")
		}
	}

	target, err := detectDocExampleTargetFromCallerFile()
	if err != nil {
		return fmt.Errorf("unable to resolve example target: %w", err)
	}

	examplesRoot, err := resolveDocExamplesRoot(opts.DocExampleOutputRoot)
	if err != nil {
		return fmt.Errorf("unable to resolve examples root: %w", err)
	}

	fileName := deriveDocExampleFileName(t.Name(), target.category)
	outDir := filepath.Join(examplesRoot, target.category, target.folderName)
	if err := os.MkdirAll(outDir, 0o755); err != nil {
		return fmt.Errorf("creating example directory %s: %w", outDir, err)
	}

	outPath := filepath.Join(outDir, fileName)
	// Add descriptive comment at top of example file
	exampleComment := fmt.Sprintf("# %s\n\n", humanizeFileName(fileName, target.folderName))
	contentWithComment := append([]byte(exampleComment), normalizeConfigContent(config)...)
	if err := writeFileAtomic(outPath, contentWithComment); err != nil {
		return fmt.Errorf("writing example file %s: %w", outPath, err)
	}

	t.Logf("[DOC-EXAMPLE] wrote %s", outPath)
	return nil
}

// firstCreateStepConfig returns the first step config suitable for a basic
// documentation example.
func firstCreateStepConfig(tc resource.TestCase) (string, bool) {
	for _, step := range tc.Steps {
		if step.ImportState {
			continue
		}
		cfg := strings.TrimSpace(step.Config)
		if cfg == "" {
			continue
		}
		return cfg, true
	}

	return "", false
}

// detectDocExampleTargetFromCallerFile derives the example category and folder
// name from the test file name on the call stack, avoiding HCL parsing.
//
// Category is determined by the parent directory name:
//   - .../test/acctest/resource/... → "resources"
//   - .../test/acctest/data/...     → "data-sources"
//
// Folder is extracted from the file name pattern
// {resource|data}_auto_f5xc_<name>_test.go → "f5xc_<name>".
func detectDocExampleTargetFromCallerFile() (docExampleTarget, error) {
	const maxFrames = 20
	for i := 2; i < maxFrames; i++ {
		_, file, _, ok := runtime.Caller(i)
		if !ok {
			break
		}
		if strings.HasSuffix(file, "vcr.go") {
			continue
		}

		dir := filepath.Base(filepath.Dir(file))
		base := filepath.Base(file)

		// derive category from parent directory
		var category string
		switch dir {
		case "resource":
			category = docExampleCategoryResources
		case "data":
			category = docExampleCategoryDataSources
		default:
			continue // not a test directory we own; keep walking
		}

		// extract folder from file name: {resource|data}_auto_f5xc_<name>_test.go
		base = strings.TrimSuffix(base, "_test.go")
		for _, prefix := range []string{"resource_auto_", "data_auto_"} {
			if strings.HasPrefix(base, prefix) {
				folderName := strings.TrimPrefix(base, prefix)
				return docExampleTarget{category: category, folderName: folderName}, nil
			}
		}
	}

	return docExampleTarget{}, fmt.Errorf("could not detect doc example target from call stack")
}

// resolveDocExamplesRoot determines where generated examples are stored.
func resolveDocExamplesRoot(override string) (string, error) {
	if strings.TrimSpace(override) != "" {
		return filepath.Clean(override), nil
	}

	_, file, _, ok := runtime.Caller(0)
	if !ok {
		return "", fmt.Errorf("unable to inspect caller for default examples path")
	}

	helperDir := filepath.Dir(file)
	return filepath.Clean(filepath.Join(helperDir, "..", "..", "examples")), nil
}

// deriveDocExampleFileName converts test names into deterministic example file
// names according to repository policy.
//
// Why: tfplugindocs discovers examples via glob patterns that require a specific
// prefix: "resource*.tf" for resources and "data-source*.tf" for data sources.
// Without the prefix the files are silently ignored during doc generation.
//
// How: The category string determines the prefix. The suffix is derived from
// the last underscore-separated token of the test name, stripped of a leading
// "with" if present, and converted to snake_case.
//
// Parameters:
//   - testName: the value of t.Name(), e.g. "TestAccResourceAutoF5XCOriginPool_withPublicIP"
//   - category: docExampleCategoryResources or docExampleCategoryDataSources
//
// Returns:
//   - A filename such as "resource_public_ip.tf" or "data-source_basic.tf"
func deriveDocExampleFileName(testName string, category string) string {
	base := testName
	if strings.Contains(base, "/") {
		parts := strings.Split(base, "/")
		base = parts[len(parts)-1]
	}

	tokens := strings.Split(base, "_")
	token := tokens[len(tokens)-1]
	if strings.HasPrefix(token, "with") && len(token) > len("with") {
		token = token[len("with"):]
	}

	snake := toSnakeCase(token)
	if snake == "" {
		snake = "example"
	}

	prefix := filenamePrefixForCategory(category)
	return prefix + snake + ".tf"
}

// filenamePrefixForCategory returns the filename prefix required by
// tfplugindocs for the given example category so that the glob patterns
// "resource*.tf" and "data-source*.tf" match the generated files.
//
// Parameters:
//   - category: one of docExampleCategoryResources or docExampleCategoryDataSources
//
// Returns:
//   - "resource_" for resources, "data-source_" for data sources, empty string otherwise.
func filenamePrefixForCategory(category string) string {
	switch category {
	case docExampleCategoryResources:
		return "resource_"
	case docExampleCategoryDataSources:
		return "data-source_"
	default:
		return ""
	}
}

// humanizeFileName converts a filename like "resource_public_ip.tf" and folder
// like "f5xc_origin_pool" into a human-readable scenario description like
// "Example: Origin Pool - Public IP".
func humanizeFileName(fileName string, folderName string) string {
	// Extract resource name from folderName (e.g., "f5xc_origin_pool" -> "origin pool")
	resourceName := folderName
	resourceName = strings.TrimPrefix(resourceName, "f5xc_")
	resourceName = strings.ReplaceAll(resourceName, "_", " ")

	// Title case resource name
	resourceParts := strings.Fields(resourceName)
	for i, word := range resourceParts {
		if len(word) > 0 {
			resourceParts[i] = strings.ToUpper(string(word[0])) + word[1:]
		}
	}
	resourceName = strings.Join(resourceParts, " ")

	// Extract scenario from fileName (e.g., "resource_public_ip.tf" -> "public ip")
	scenario := strings.TrimSuffix(fileName, ".tf")
	scenario = strings.TrimPrefix(scenario, "resource_")
	scenario = strings.TrimPrefix(scenario, "data-source_")
	scenario = strings.ReplaceAll(scenario, "_", " ")

	// Title case scenario
	scenarioParts := strings.Fields(scenario)
	for i, word := range scenarioParts {
		if len(word) > 0 {
			scenarioParts[i] = strings.ToUpper(string(word[0])) + word[1:]
		}
	}
	scenario = strings.Join(scenarioParts, " ")

	return fmt.Sprintf("Example: %s - %s", resourceName, scenario)
}

// toSnakeCase converts camel/pascal text into snake_case and keeps only
// portable filename characters.
func toSnakeCase(input string) string {
	input = strings.TrimSpace(input)
	if input == "" {
		return ""
	}

	var out bytes.Buffer
	runes := []rune(input)
	for idx, cur := range runes {
		if unicode.IsUpper(cur) {
			if idx > 0 {
				prev := runes[idx-1]
				nextLower := idx+1 < len(runes) && unicode.IsLower(runes[idx+1])
				if unicode.IsLower(prev) || unicode.IsDigit(prev) || nextLower {
					out.WriteRune('_')
				}
			}
			out.WriteRune(unicode.ToLower(cur))
			continue
		}

		if unicode.IsLetter(cur) || unicode.IsDigit(cur) {
			out.WriteRune(unicode.ToLower(cur))
			continue
		}

		out.WriteRune('_')
	}

	cleaned := collapseUnderscores(out.String())
	return strings.Trim(cleaned, "_")
}

// collapseUnderscores collapses sequential underscore runs to a single
// underscore.
func collapseUnderscores(input string) string {
	if input == "" {
		return ""
	}

	var out bytes.Buffer
	lastUnderscore := false
	for _, cur := range input {
		if cur == '_' {
			if lastUnderscore {
				continue
			}
			lastUnderscore = true
			out.WriteRune(cur)
			continue
		}

		lastUnderscore = false
		out.WriteRune(cur)
	}

	return out.String()
}

// normalizeConfigContent ensures deterministic final newline for generated
// example files.
func normalizeConfigContent(content string) []byte {
	trimmed := strings.TrimSpace(content)
	return []byte(trimmed + "\n")
}

// writeFileAtomic writes content to path atomically by using a temp file in
// the same directory followed by rename.
func writeFileAtomic(path string, content []byte) (retErr error) {
	dir := filepath.Dir(path)
	tmp, err := os.CreateTemp(dir, ".doc-example-*.tf")
	if err != nil {
		return err
	}

	tmpName := tmp.Name()
	defer func() {
		_ = tmp.Close()
		if retErr != nil {
			_ = os.Remove(tmpName)
		}
	}()

	if _, err := tmp.Write(content); err != nil {
		retErr = err
		return retErr
	}

	if err := tmp.Close(); err != nil {
		retErr = err
		return retErr
	}

	if err := os.Rename(tmpName, path); err != nil {
		retErr = err
		return retErr
	}

	return nil
}

// vcrRecord runs the test case in recording mode: all HTTP interactions are
// captured and persisted to cassetteName on disk.
func vcrRecord(t *testing.T, tc resource.TestCase, cassetteName string) {
	t.Helper()
	log.Printf("[VCR] RECORDING cassette: %s", cassetteName)

	rec, err := recorder.New(cassetteName,
		recorder.WithMode(recorder.ModeRecordOnly),
		recorder.WithSkipRequestLatency(true),
		// recorder.WithReplayableInteractions(true),
		recorder.WithHook(redactSensitiveHeaders, recorder.BeforeSaveHook),
		recorder.WithMatcher(methodURLMatcher),
	)
	if err != nil {
		t.Fatalf("[VCR] failed to create recorder: %v", err)
	}

	installRecorder(t, rec)
	resource.Test(t, tc)
}

// vcrReplay runs the test case in replay mode: all HTTP interactions are served
// from the cassette file; no live network requests are made.
func vcrReplay(t *testing.T, tc resource.TestCase, cassetteName string) {
	t.Helper()
	log.Printf("[VCR] REPLAYING cassette: %s", cassetteName)

	rec, err := recorder.New(cassetteName,
		recorder.WithMode(recorder.ModeReplayOnly),
		recorder.WithSkipRequestLatency(true),
		// recorder.WithReplayableInteractions(true),
		recorder.WithMatcher(methodURLMatcher),
	)
	if err != nil {
		t.Fatalf("[VCR] failed to load cassette for replay: %v", err)
	}

	installRecorder(t, rec)
	resource.Test(t, tc)
}

// installRecorder wires rec into the global VCR transport hook so that every
// http.Client in the provider goes through the recorder.  It registers a
// t.Cleanup to stop the recorder and restore the default transport.
func installRecorder(t *testing.T, rec *recorder.Recorder) {
	t.Helper()

	client.SetVCRTransportWrapper(func(_ http.RoundTripper) http.RoundTripper {
		return rec
	})

	t.Cleanup(func() {
		if err := rec.Stop(); err != nil {
			t.Errorf("[VCR] failed to stop recorder: %v", err)
		}
		client.SetVCRTransportWrapper(nil)
	})
}

// cassettePath derives a cassette file path from t.Name().
//
// It uses runtime.Caller to locate the source file of the test function that
// called VcrTest, then places cassettes in a "cassettes/" sub-directory next to
// that file.  This automatically separates resource cassettes from data-source
// cassettes because the test files live in different directories.
//
// Example output:
//
//	.../test/acctest/resource/cassettes/TestAccResourceAutoF5XCNamespace_basic
func cassettePath(t *testing.T) (string, error) {
	t.Helper()

	// Walk up the call stack to find the first frame outside this package.
	// Frames: 0=cassettePath, 1=VcrTest, 2=test function (what we want).
	const maxFrames = 10
	for i := 2; i < maxFrames; i++ {
		_, file, _, ok := runtime.Caller(i)
		if !ok {
			break
		}
		// Stop as soon as we leave this file.
		if !strings.HasSuffix(file, "vcr.go") {
			dir := filepath.Dir(file)
			name := sanitizeTestName(t.Name())
			return filepath.Join(dir, "cassettes", name), nil
		}
	}

	return "", fmt.Errorf("could not find caller outside vcr.go for test %s", t.Name())
}

// sanitizeTestName converts a test name into a safe file-system path component
// by replacing slashes and spaces with underscores.
func sanitizeTestName(name string) string {
	name = strings.ReplaceAll(name, "/", "_")
	name = strings.ReplaceAll(name, " ", "_")
	return name
}

// methodURLMatcher is a [cassette.MatcherFunc] that matches recorded
// interactions by HTTP method and full URL.  This gives reliable matching
// without depending on request body content, which may contain timestamps or
// other non-deterministic values.
func methodURLMatcher(r *http.Request, i cassette.Request) bool {
	if r.Method != i.Method {
		return false
	}

	recordedURL, err := url.Parse(i.URL)
	if err != nil {
		return false
	}

	return normalizeURLForMatch(r.URL) == normalizeURLForMatch(recordedURL)
}

// normalizeURLForMatch normalizes known volatile host parts before matching.
// For *.volterra.us hosts, the first two labels (tenant and env, e.g.
// customer1.crt) are treated as wildcards to make replay portable.
func normalizeURLForMatch(u *url.URL) string {
	if u == nil {
		return ""
	}

	n := *u
	host := strings.ToLower(n.Hostname())
	if isVolterraHost(host) {
		parts := strings.Split(host, ".")
		if len(parts) >= 4 {
			parts[0] = "*"
			parts[1] = "*"
			host = strings.Join(parts, ".")
		}
	}

	if port := n.Port(); port != "" {
		n.Host = net.JoinHostPort(host, port)
	} else {
		n.Host = host
	}

	return n.String()
}

func isVolterraHost(host string) bool {
	parts := strings.Split(host, ".")
	if len(parts) < 3 {
		return false
	}
	return parts[len(parts)-2] == "volterra" && parts[len(parts)-1] == "us"
}

// redactSensitiveHeaders is a [recorder.HookFunc] that replaces credential
// values in request headers before the cassette is written to disk, so that
// API tokens and tenant identifiers are never stored in the repository.
func redactSensitiveHeaders(i *cassette.Interaction) error {
	for _, h := range []string{
		"Authorization",
		"X-Volterra-Apigw-Tenant",
		"Cookie",
	} {
		if i.Request.Headers.Get(h) != "" {
			i.Request.Headers.Set(h, "REDACTED")
		}
	}
	return nil
}
